# [ A©t0r © ] FINAL ENCRYPTED MONOLITH
$Locked_Blob = ''
$NodeID = '57BF917347C0B4DC6D4ABD3F6B16405A3D97971ADF7E52FA55CFEA244C289BEA'

$Pass = Read-Host "Введите секретное слово A©tor для регенерации узла" -AsSecureString
$BSTR = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($Pass)
$Key = [System.Text.Encoding]::UTF8.GetBytes([System.Runtime.InteropServices.Marshal]::PtrToStringAuto($BSTR))

$Bytes = [Convert]::FromBase64String($Locked_Blob)
$Decrypted = New-Object Byte[] $Bytes.Length
for($i=0; $i -lt $Bytes.Length; $i++) {
    $Decrypted[$i] = $Bytes[$i] -bxor $Key[$i % $Key.Length]
}

try {
    $Data = [System.Text.Encoding]::UTF8.GetString($Decrypted) | ConvertFrom-Json
    Write-Host "[ OK ] Доступ разрешен. Личность A©tor подтверждена." -ForegroundColor Green
    
    foreach ($item in $Data.psobject.properties) {
        $OutPath = ".\REGENERATED_$NodeID$(.Name)"
        [System.IO.File]::WriteAllBytes($OutPath, [Convert]::FromBase64String($item.Value))
        Write-Host "    -> Восстановлен компонент: $(.Name)" -ForegroundColor Gray
    }
} catch {
    Write-Host "[ ! ] ОШИБКА: Неверное секретное слово. Доступ к узлу заблокирован." -ForegroundColor Red
}
